data.document:
query MexFetchNewsletterDehydratedJobQuery($fetch_pinned_messages, $fetch_wamo_sub, $input) {
  xwa2_newsletter {
    id
    thread_metadata {
      subscribers_count
      verification
      settings {
        reaction_codes {
          value
          wamo_sub {
            plan_id
            pinned_messages {
              message_id
              expiry_ts
              viewer_metadata {
                wamo_sub_status
              }
            }
          }
        }
      }
    }
  }
}
